domain = []
if order_name:
    domain.append(['name', 'ilike', order_name])
if partner_name:
    partner = env['res.partner'].sudo().search([['name', 'ilike', partner_name]], limit=5)
    if not partner:
        ai['result'] = f"ERROR: Cannot find customer '{partner_name}'."
    else:
        domain.append(['partner_id', 'in', partner.ids])
if state:
    domain.append(['state', '=', state])

if 'result' not in ai:
    if not domain:
        ai['result'] = "ERROR: Provide at least one search criterion (order_name, partner_name, or state)."
    else:
        orders = env['sale.order'].sudo().search(domain, limit=10, order='date_order desc')
        if not orders:
            ai['result'] = "No orders found matching the criteria."
        else:
            lines = ["Found orders:"]
            for o in orders:
                lines.append(
                    f" {o.name} | {o.partner_id.display_name} | "
                    f"state={o.state} | total={o.amount_total} {o.currency_id.name} | "
                    f"invoice_status={o.invoice_status}"
                )
            ai['result'] = "\n".join(lines)

partner = env['res.partner'].sudo().search([['name', 'ilike', partner_name]], limit=5)
if not partner:
    ai['result'] = f"ERROR: Customer '{partner_name}' not found. Use 'AI Sale: Create Customer' first."
elif len(partner) > 1:
    names = ", ".join(f"{p.display_name}(ID:{p.id})" for p in partner)
    ai['result'] = f"ERROR: Multiple customers match '{partner_name}': {names}. Please be more specific."
else:
    partner = partner[0]
    order_lines = []
    errors = []

    for pname, qty_str, price_str in zip(product_names or [], quantities or [], unit_prices or []):
        # Variant-aware resolution: 'PVC板(昆明,8mm)' picks the matching variant
        norm = (pname or '').replace('（', '(').replace('）', ')').strip()
        base = norm.split('(')[0].strip() if '(' in norm else norm
        inner = norm.split('(', 1)[1].split(')')[0] if '(' in norm else ''
        for sep in ('，', '、', '|', '；', ';'):
            inner = inner.replace(sep, ',')
        wanted = [w.strip().lower() for w in inner.split(',') if w.strip()]

        product = env['product.product'].sudo().search([['default_code', '=ilike', base]], limit=1)
        if not product:
            tmpl = env['product.template'].sudo().search([['name', '=ilike', base]], limit=1)
            if not tmpl:
                tmpl = env['product.template'].sudo().search([['name', 'ilike', base]], limit=1)
            if not tmpl:
                errors.append(f"Product '{pname}' not found.")
                continue
            cand = tmpl.product_variant_ids
            if wanted:
                # two passes: exact value match first ('5mm' must not hit '15mm'),
                # substring only as fallback for partial input
                matched = env['product.product'].sudo()
                loose = env['product.product'].sudo()
                for p in cand:
                    vname_list = [(n or '').lower() for n in p.product_template_attribute_value_ids.mapped('name')]
                    exact_ok = True
                    loose_ok = True
                    for w in wanted:
                        if w not in vname_list:
                            exact_ok = False
                        hit = False
                        for n in vname_list:
                            if w in n:
                                hit = True
                                break
                        if not hit:
                            loose_ok = False
                    if exact_ok:
                        matched += p
                    if loose_ok:
                        loose += p
                cand = matched if matched else loose
            if len(cand) == 1:
                product = cand
            elif not cand:
                avail = "; ".join(f"ID {p.id}: {p.display_name}" for p in tmpl.product_variant_ids[:12])
                errors.append(
                    f"'{pname}': no variant matches ({inner}). Existing variants: {avail}. "
                    "Configure the missing combination first (AI Skill: Configure Product Variants) "
                    "or ask the user to pick one of the existing variants."
                )
                continue
            else:
                cand_names = "; ".join(f"ID {p.id}: {p.display_name}" for p in cand[:12])
                errors.append(
                    f"'{pname}': several variants match — ask the user which one (quick options): {cand_names}"
                )
                continue

        try:
            qty = float(qty_str) if qty_str else 1.0
        except (ValueError, TypeError):
            qty = 1.0

        line_vals = {
            'product_id': product.id,
            'product_uom_qty': qty,
            'name': product.display_name,
        }
        if price_str and price_str.strip():
            try:
                line_vals['price_unit'] = float(price_str)
            except (ValueError, TypeError):
                pass

        order_lines.append((0, 0, line_vals))

    if errors:
        ai['result'] = "ERROR: " + "; ".join(errors)
    elif not order_lines:
        ai['result'] = "ERROR: No valid order lines could be built."
    else:
        order_vals = {'partner_id': partner.id, 'order_line': order_lines}
        if note:
            order_vals['note'] = note

        order = env['sale.order'].sudo().create(order_vals)

        summary = ""
        for line in order.order_line:
            summary += (
                f"\n - {line.product_id.display_name}: "
                f"qty={line.product_uom_qty} x {line.price_unit} = {line.price_subtotal}"
            )

        ai['result'] = (
            f"Quotation created successfully.\n"
            f" Reference: {order.name}\n"
            f" Customer : {order.partner_id.display_name}\n"
            f" Amount : {order.amount_total} {order.currency_id.name}\n"
            f" Lines :{summary}"
        )

