else:
    # Token match on display_name so 'PVC板(昆明,8mm)' finds the exact variant line
    norm = (product_name or '').replace('（', ',').replace('）', ',').replace('(', ',').replace(')', ',').lower()
    for sep in ('，', '、', '|', '；', ';'):
        norm = norm.replace(sep, ',')
    tokens = [t.strip() for t in norm.split(',') if t.strip()]
    line = env['sale.order.line'].sudo()
    for candidate_line in order.order_line:
        if not candidate_line.product_id:
            continue
        disp = (candidate_line.product_id.display_name or '').lower()
        ok = True
        for t in tokens:
            if t not in disp:
                ok = False
                break
        if ok:
            line += candidate_line
    if not line:
        avail = "\n".join(f"  - {l.product_id.display_name}" for l in order.order_line[:15] if l.product_id)
        ai['result'] = (
