            f"Lines in this order:\n{avail}"
        )
    elif len(line) > 1:
        names = "; ".join(line.mapped('product_id.display_name'))
        ai['result'] = f"ERROR: Multiple lines match '{product_name}' in {order_name}: {names}. Be more specific (include the variant values)."
